{
  "name": "Trading Journal Pro",
  "description": "A high-end, professional trading journal for tracking weekly market insights, asset strategies, and technical analysis with AI-powered refinement."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type AssetStatus = 'Breakout' | 'Ranging' | 'Consolidation' | 'Bearish' | 'Bullish' | 'Key Level';

export interface MarketInsight {
  id: string;
  symbol: string;
  fullName: string;
  category: string;
  status: AssetStatus;
  relatedAssets: string[];
  focusPoints: string;
  strategy: string;
  keyLevel?: string;
  updatedAt: number;
}

export type Category = 'All' | 'Indices' | 'Crypto' | 'Tech' | 'Semiconductors' | 'Commodities';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const refineMarketInsight = async (rawInput: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Refine this market insight into a professional trading journal format.
      Input: ${rawInput}

      Return a structured JSON object.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            symbol: { type: Type.STRING },
            fullName: { type: Type.STRING },
            category: { type: Type.STRING, description: 'One of: Indices, Crypto, Tech, Semiconductors, Commodities' },
            status: { type: Type.STRING, description: 'One of: Breakout, Ranging, Consolidation, Bearish, Bullish, Key Level' },
            relatedAssets: { type: Type.ARRAY, items: { type: Type.STRING } },
            focusPoints: { type: Type.STRING },
            strategy: { type: Type.STRING },
            keyLevel: { type: Type.STRING },
          },
          required: ['symbol', 'fullName', 'category', 'status', 'focusPoints', 'strategy']
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini refinement error:", error);
    return null;
  }
};

export const generateWeeklySummary = async (insights: any[]) => {
  try {
    const context = JSON.stringify(insights);
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Based on my current market insights: ${context}, provide a concise weekly executive summary (max 3 sentences) and the top 3 items I should watch next week. Use professional financial tone. Include Google Search results if possible for macro context.`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini summary error:", error);
    return "Failed to generate AI summary. Please check your connection.";
  }
};

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { ArrowRight, TrendingUp, AlertCircle, Maximize2 } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
}

const getStatusColor = (status: AssetStatus) => {
  switch (status) {
    case 'Breakout': return 'bg-green-100 text-green-700 border-green-200';
    case 'Bullish': return 'bg-blue-100 text-blue-700 border-blue-200';
    case 'Bearish': return 'bg-red-100 text-red-700 border-red-200';
    case 'Key Level': return 'bg-orange-100 text-orange-700 border-orange-200';
    default: return 'bg-gray-100 text-gray-700 border-gray-200';
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete }) => {
  return (
    <div className="group relative bg-[#f9f9f9] border border-transparent hover:border-gray-200 rounded-2xl p-8 transition-all duration-300 flex flex-col h-full shadow-sm hover:shadow-md">
      <div className="flex justify-between items-start mb-6">
        <div>
          <h3 className="text-3xl font-serif text-gray-900 mb-1">{insight.symbol}</h3>
          <p className="text-sm text-gray-500 font-medium tracking-wide uppercase">{insight.fullName}</p>
        </div>
        <span className={`px-3 py-1 rounded-full text-[11px] font-bold tracking-wider uppercase border ${getStatusColor(insight.status)}`}>
          {insight.status}
        </span>
      </div>

      <div className="space-y-6 flex-grow">
        <div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-2">Related Assets</p>
          <div className="flex flex-wrap gap-2">
            {insight.relatedAssets.map((asset, idx) => (
              <span key={idx} className="text-sm font-semibold text-gray-700">{asset}{idx < insight.relatedAssets.length - 1 ? ',' : ''}</span>
            ))}
          </div>
        </div>

        <div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-2">Observations</p>
          <p className="text-sm text-gray-700 leading-relaxed font-medium">{insight.focusPoints}</p>
        </div>

        {insight.keyLevel && (
          <div>
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-2">Key Level</p>
            <p className="text-xl font-serif text-red-500">{insight.keyLevel}</p>
          </div>
        )}

        <div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-2">Entry Strategy</p>
          <p className="text-sm text-gray-700 leading-relaxed italic">{insight.strategy}</p>
        </div>
      </div>

      <div className="mt-8 pt-6 border-t border-gray-100 flex justify-between items-center">
        <button className="flex items-center text-xs font-bold text-gray-900 hover:text-black transition-colors">
          VIEW ON-CHAIN DATA <ArrowRight className="ml-2 w-3 h-3" />
        </button>

        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={() => onEdit(insight)}
            className="p-2 text-gray-400 hover:text-gray-900 transition-colors"
          >
            <TrendingUp className="w-4 h-4" />
          </button>
          <button 
            onClick={() => onDelete(insight.id)}
            className="p-2 text-gray-400 hover:text-red-500 transition-colors"
          >
            <AlertCircle className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MarketCard;

import React, { useState } from 'react';
import { MarketInsight, AssetStatus, Category } from '../types';
import { X, Sparkles, Loader2 } from 'lucide-react';
import { refineMarketInsight } from '../services/geminiService';
import { CATEGORIES } from '../constants';

interface InsightFormProps {
  initialData?: MarketInsight;
  onSave: (data: Partial<MarketInsight>) => void;
  onCancel: () => void;
}

const InsightForm: React.FC<InsightFormProps> = ({ initialData, onSave, onCancel }) => {
  const [formData, setFormData] = useState<Partial<MarketInsight>>(
    initialData || {
      symbol: '',
      fullName: '',
      category: 'Tech',
      status: 'Consolidation',
      relatedAssets: [],
      focusPoints: '',
      strategy: '',
      keyLevel: '',
    }
  );
  const [refining, setRefining] = useState(false);
  const [rawText, setRawText] = useState('');

  const handleRefine = async () => {
    if (!rawText.trim()) return;
    setRefining(true);
    const refined = await refineMarketInsight(rawText);
    if (refined) {
      setFormData(prev => ({ ...prev, ...refined }));
    }
    setRefining(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50">
          <h2 className="text-xl font-serif text-gray-900">
            {initialData ? 'Update Insight' : 'New Market Insight'}
          </h2>
          <button onClick={onCancel} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
          {!initialData && (
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
              <label className="text-xs font-bold text-blue-600 uppercase tracking-widest mb-2 block">AI Magic Refinement</label>
              <div className="flex gap-3">
                <textarea
                  className="flex-grow p-3 text-sm rounded-lg border border-blue-200 focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Paste raw notes like: BTC looks weak at 90k, maybe watch 85k for bounce..."
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  rows={2}
                />
                <button
                  type="button"
                  onClick={handleRefine}
                  disabled={refining}
                  className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 self-end disabled:opacity-50"
                >
                  {refining ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                  Refine
                </button>
              </div>
            </div>
          )}

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Symbol</label>
              <input
                required
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all"
                value={formData.symbol}
                onChange={(e) => setFormData({ ...formData, symbol: e.target.value.toUpperCase() })}
                placeholder="e.g. BTC"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Full Name</label>
              <input
                required
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all"
                value={formData.fullName}
                onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
                placeholder="e.g. Bitcoin"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Category</label>
              <select
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all appearance-none"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              >
                {CATEGORIES.filter(c => c !== 'All').map(c => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Status</label>
              <select
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all appearance-none"
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as AssetStatus })}
              >
                <option value="Breakout">Breakout</option>
                <option value="Ranging">Ranging</option>
                <option value="Consolidation">Consolidation</option>
                <option value="Bullish">Bullish</option>
                <option value="Bearish">Bearish</option>
                <option value="Key Level">Key Level</option>
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Observations</label>
            <textarea
              required
              rows={3}
              className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all"
              value={formData.focusPoints}
              onChange={(e) => setFormData({ ...formData, focusPoints: e.target.value })}
              placeholder="Key observations about current price action..."
            />
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Entry Strategy</label>
              <textarea
                required
                rows={2}
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all"
                value={formData.strategy}
                onChange={(e) => setFormData({ ...formData, strategy: e.target.value })}
                placeholder="Your trade plan..."
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Key Level (Optional)</label>
              <input
                className="w-full p-3 bg-gray-50 border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all"
                value={formData.keyLevel}
                onChange={(e) => setFormData({ ...formData, keyLevel: e.target.value })}
                placeholder="e.g. 110.00"
              />
            </div>
          </div>

          <div className="pt-6 border-t border-gray-100 flex gap-4">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-3 px-6 rounded-xl border border-gray-200 text-gray-600 font-bold hover:bg-gray-50 transition-colors"
            >
              Discard
            </button>
            <button
              type="submit"
              className="flex-1 py-3 px-6 rounded-xl bg-gray-900 text-white font-bold hover:bg-black transition-colors"
            >
              {initialData ? 'Update Insight' : 'Save Insight'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default InsightForm;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, AppState } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Sparkles, MessageSquare, ChevronRight } from 'lucide-react';
import { generateWeeklySummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v1');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('All');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [weeklySummary, setWeeklySummary] = useState<string | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);

  useEffect(() => {
    localStorage.setItem('trading_journal_v1', JSON.stringify(insights));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    if (activeCategory === 'All') return insights;
    return insights.filter(i => i.category === activeCategory);
  }, [insights, activeCategory]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: Date.now() } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        updatedAt: Date.now(),
        ...data as any,
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('Are you sure you want to remove this insight?')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleGenerateSummary = async () => {
    setIsSummarizing(true);
    const summary = await generateWeeklySummary(insights);
    setWeeklySummary(summary);
    setIsSummarizing(false);
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <LayoutGrid className="w-6 h-6 text-gray-900" />
            <h1 className="text-2xl font-serif text-gray-900">Trading.Journal</h1>
          </div>

          <nav className="hidden md:flex items-center gap-8">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`text-sm font-medium transition-all relative py-2 ${
                  activeCategory === cat ? 'text-gray-900' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                {cat}
                {activeCategory === cat && (
                  <span className="absolute bottom-0 left-0 w-full h-0.5 bg-red-500 rounded-full" />
                )}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <button 
              onClick={handleGenerateSummary}
              disabled={isSummarizing}
              className="hidden lg:flex items-center gap-2 text-xs font-bold bg-white border border-gray-200 px-4 py-2 rounded-full hover:bg-gray-50 transition-colors disabled:opacity-50"
            >
              {isSummarizing ? 'ANALYZING...' : <><Sparkles className="w-3 h-3 text-blue-500" /> AI SUMMARY</>}
            </button>
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-gray-900 text-white p-2 md:px-5 md:py-2 rounded-full hover:bg-black transition-all flex items-center gap-2"
            >
              <Plus className="w-5 h-5" />
              <span className="hidden md:inline font-bold text-xs">NEW INSIGHT</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow max-w-7xl mx-auto px-6 py-12 w-full">
        {/* Weekly AI Summary Banner */}
        {weeklySummary && (
          <div className="mb-16 bg-white border border-gray-100 p-8 rounded-3xl shadow-sm flex items-start gap-6 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-blue-50 p-3 rounded-2xl">
              <MessageSquare className="w-6 h-6 text-blue-600" />
            </div>
            <div className="flex-grow">
              <div className="flex justify-between items-center mb-2">
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Market Intelligence Summary</h4>
                <button onClick={() => setWeeklySummary(null)} className="text-gray-400 hover:text-gray-600">
                  <Plus className="w-4 h-4 rotate-45" />
                </button>
              </div>
              <div className="prose prose-sm text-gray-700 leading-relaxed max-w-none font-medium italic">
                {weeklySummary.split('\n').map((line, i) => <p key={i} className="mb-2">{line}</p>)}
              </div>
            </div>
          </div>
        )}

        <div className="flex items-center gap-4 mb-10">
          <h2 className="text-4xl font-serif text-gray-900">Asset Strategy</h2>
          <div className="h-[1px] bg-gray-100 flex-grow mt-2" />
        </div>

        {filteredInsights.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredInsights.map(insight => (
              <MarketCard 
                key={insight.id} 
                insight={insight} 
                onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                onDelete={handleDeleteInsight}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-32 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-100">
            <div className="max-w-xs mx-auto">
              <LayoutGrid className="w-12 h-12 text-gray-200 mx-auto mb-4" />
              <h3 className="text-lg font-serif text-gray-600 mb-2">No Insights Yet</h3>
              <p className="text-sm text-gray-400 mb-6">Start tracking your market views by adding your first asset strategy.</p>
              <button 
                onClick={() => setShowForm(true)}
                className="inline-flex items-center gap-2 px-6 py-2 bg-white border border-gray-200 rounded-full font-bold text-xs text-gray-900 hover:bg-gray-50"
              >
                Create Strategy <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-100 py-12 bg-white">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex flex-col items-center md:items-start">
            <div className="flex items-center gap-2 mb-2">
              <LayoutGrid className="w-5 h-5 text-gray-900" />
              <span className="font-serif text-lg">Trading.Journal</span>
            </div>
            <p className="text-xs text-gray-400 font-medium">© 2024 Professional Market Insights System</p>
          </div>

          <div className="flex gap-12 text-center md:text-left">
            <div>
              <p className="text-[10px] font-bold text-gray-300 uppercase tracking-widest mb-4">Resources</p>
              <ul className="space-y-2 text-xs font-bold text-gray-500">
                <li><a href="#" className="hover:text-gray-900 transition-colors">Documentation</a></li>
                <li><a href="#" className="hover:text-gray-900 transition-colors">API Guide</a></li>
              </ul>
            </div>
            <div>
              <p className="text-[10px] font-bold text-gray-300 uppercase tracking-widest mb-4">Support</p>
              <ul className="space-y-2 text-xs font-bold text-gray-500">
                <li><a href="#" className="hover:text-gray-900 transition-colors">Contact</a></li>
                <li><a href="#" className="hover:text-gray-900 transition-colors">Privacy</a></li>
              </ul>
            </div>
          </div>
        </div>
      </footer>

      {/* Forms */}
      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

export type AssetStatus = '突破' | '震荡' | '整理' | '看跌' | '看涨' | '关键位置';

export interface MarketInsight {
  id: string;
  symbol: string;
  fullName: string;
  category: string;
  status: AssetStatus;
  relatedAssets: string[];
  focusPoints: string;
  strategy: string;
  keyLevel?: string;
  updatedAt: number;
}

export type Category = '全部' | '指数' | '加密货币' | '科技' | '半导体' | '大宗商品';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
}

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { ArrowRight, Edit2, Trash2, Calendar } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
}

const getStatusColor = (status: AssetStatus) => {
  switch (status) {
    case '突破': return 'bg-green-50 text-green-600 border-green-100';
    case '看涨': return 'bg-blue-50 text-blue-600 border-blue-100';
    case '看跌': return 'bg-red-50 text-red-600 border-red-100';
    case '关键位置': return 'bg-orange-50 text-orange-600 border-orange-100';
    default: return 'bg-gray-50 text-gray-500 border-gray-100';
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  return (
