import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, ChevronRight, Hash, Filter } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 按日期分组生成时间轴
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    // 按时间倒序
    return [...result].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [insights, activeCategory, selectedMonth]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: Date.now() } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        updatedAt: Date.now(),
        ...data as any,
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col">
      {/* 导航栏 */}
      <header className="sticky top-0 z-40 bg-white/90 backdrop-blur-xl border-b border-gray-100 px-6 h-20">
        <div className="max-w-7xl mx-auto flex items-center justify-between h-full">
          <div className="flex items-center gap-3">
            <div className="bg-gray-900 p-2 rounded-xl">
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-gray-900 tracking-tight">市场周志</h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Trading Journal Pro</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-6 py-2.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2 shadow-lg shadow-red-100 font-bold text-sm"
            >
              <Plus className="w-4 h-4" />
              <span>新记录</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-6 py-10 w-full flex flex-col lg:flex-row gap-10">
        {/* 左侧边栏：分类与时间轴 */}
        <aside className="lg:w-64 space-y-10 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-6 px-1">
              <Filter className="w-4 h-4 text-gray-400" />
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">视图分类</h3>
            </div>
            <nav className="space-y-1">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between ${
                    activeCategory === cat ? 'bg-gray-900 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Hash className={`w-3.5 h-3.5 ${activeCategory === cat ? 'text-red-400' : 'text-gray-300'}`} />
                    {cat}
                  </span>
                  {activeCategory === cat && <ChevronRight className="w-3 h-3" />}
                </button>
              ))}
            </nav>
          </div>

          <div>
            <div className="flex items-center gap-2 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">时间归档</h3>
            </div>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                全部时间
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Calendar className="w-3.5 h-3.5 opacity-50" />
                    {month}
                  </span>
                  <span className="text-[10px] bg-gray-100 text-gray-400 px-2 py-0.5 rounded-full">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* 主内容区域 */}
        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <span className="h-1.5 w-8 bg-red-500 rounded-full"></span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">当前筛选: {activeCategory} / {selectedMonth || '所有时间'}</span>
              </div>
              <h2 className="text-4xl font-bold text-gray-900 tracking-tight">
                市场策略分析
              </h2>
            </div>
            <div className="text-sm text-gray-400 font-medium">
              共计 {filteredInsights.length} 条见解
            </div>
          </div>

          {filteredInsights.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
              {filteredInsights.map(insight => (
                <MarketCard 
                  key={insight.id} 
                  insight={insight} 
                  onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                  onDelete={handleDeleteInsight}
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white rounded-[3rem] border border-gray-100">
              <div className="max-w-xs mx-auto">
                <div className="w-16 h-16 bg-gray-50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                  <Clock className="w-8 h-8 text-gray-200" />
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-2">暂无匹配记录</h3>
                <p className="text-sm text-gray-400 mb-8 leading-relaxed">该分类或时间段内没有记录，您可以尝试切换分类或创建新的分析记录。</p>
                <button 
                  onClick={() => setShowForm(true)}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-gray-900 rounded-2xl font-bold text-sm text-white hover:bg-black transition-all shadow-xl shadow-gray-200"
                >
                  开始记录新分析
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* 页脚 */}
      <footer className="mt-auto border-t border-gray-100 py-10 bg-white">
        <div className="max-w-7xl mx-auto px-6 text-center">
          <p className="text-[10px] text-gray-300 font-bold uppercase tracking-[0.3em]">个人交易日记系统 · 每周行情洞察记录</p>
        </div>
      </footer>

      {/* 弹窗表单 */}
      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

