import React, { useState } from 'react';
import { MarketInsight, AssetStatus, Category } from '../types';
import { X, Calendar as CalendarIcon } from 'lucide-react';
import { CATEGORIES } from '../constants';

interface InsightFormProps {
  initialData?: MarketInsight;
  onSave: (data: Partial<MarketInsight>) => void;
  onCancel: () => void;
}

const InsightForm: React.FC<InsightFormProps> = ({ initialData, onSave, onCancel }) => {
  const [formData, setFormData] = useState<Partial<MarketInsight>>(
    initialData || {
      symbol: '',
      fullName: '',
      category: '科技',
      status: '整理',
      relatedAssets: [],
      focusPoints: '',
      strategy: '',
      keyLevel: '',
      updatedAt: Date.now(),
    }
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  // 格式化时间戳为 HTML5 date input 要求的 YYYY-MM-DD
  const formatDateForInput = (timestamp?: number) => {
    if (!timestamp) return new Date().toISOString().split('T')[0];
    return new Date(timestamp).toISOString().split('T')[0];
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md">
      <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in fade-in zoom-in duration-300 border border-gray-100">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
          <h2 className="text-xl font-bold text-gray-900">
            {initialData ? '更新市场观点' : '记录新观点'}
          </h2>
          <button onClick={onCancel} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-5 max-h-[85vh] overflow-y-auto">
          {/* 日期选择 */}
          <div className="space-y-1.5">
            <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-1">
              <CalendarIcon className="w-3 h-3" /> 记录日期
            </label>
            <input
              type="date"
              className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm font-medium"
              value={formatDateForInput(formData.updatedAt)}
              onChange={(e) => {
                // 将日期字符串转回时间戳，保持 UTC 正午以避免时区偏差导致日期跳变
                const selectedDate = new Date(e.target.value);
                setFormData({ ...formData, updatedAt: selectedDate.getTime() });
              }}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">代码 (Symbol)</label>
              <input
                required
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm font-bold"
                value={formData.symbol}
                onChange={(e) => setFormData({ ...formData, symbol: e.target.value.toUpperCase() })}
                placeholder="例如: BTC"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">全称</label>
              <input
                required
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm"
                value={formData.fullName}
                onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
                placeholder="例如: 比特币"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">所属分类</label>
              <select
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all appearance-none text-sm"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              >
                {CATEGORIES.filter(c => c !== '全部').map(c => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">当前行情状态</label>
              <select
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all appearance-none text-sm"
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as AssetStatus })}
              >
                <option value="突破">突破 (Breakout)</option>
                <option value="震荡">震荡 (Ranging)</option>
                <option value="整理">整理 (Consolidation)</option>
                <option value="看涨">看涨 (Bullish)</option>
                <option value="看跌">看跌 (Bearish)</option>
                <option value="关键位置">关键位置 (Key Level)</option>
              </select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">核心观点点位/观察</label>
            <textarea
              required
              rows={3}
              className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm leading-relaxed"
              value={formData.focusPoints}
              onChange={(e) => setFormData({ ...formData, focusPoints: e.target.value })}
              placeholder="记录关键的价格行为或基本面变化..."
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">拟定策略</label>
              <textarea
                required
                rows={2}
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm leading-relaxed"
                value={formData.strategy}
                onChange={(e) => setFormData({ ...formData, strategy: e.target.value })}
                placeholder="进场点位或操作建议..."
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">关键价格 (可选)</label>
              <input
                className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm"
                value={formData.keyLevel}
                onChange={(e) => setFormData({ ...formData, keyLevel: e.target.value })}
                placeholder="例如: 110.00"
              />
            </div>
          </div>

          <div className="pt-6 flex gap-3">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-3.5 px-6 rounded-2xl border border-gray-100 text-gray-500 font-bold text-sm hover:bg-gray-50 transition-colors"
            >
              取消
            </button>
            <button
              type="submit"
              className="flex-1 py-3.5 px-6 rounded-2xl bg-gray-900 text-white font-bold text-sm hover:bg-black transition-colors shadow-lg shadow-gray-200"
            >
              {initialData ? '更新记录' : '确认保存'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

