            <input
              type="date"
              className="w-full p-3 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-200 rounded-xl outline-none transition-all text-sm font-medium"
              value={formatDateForInput(formData.updatedAt)}
              onChange={(e) => {
                // 将日期字符串转回时间戳
                const selectedDate = new Date(e.target.value);
                setFormData({ ...formData, updatedAt: selectedDate.getTime() });
              }}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">代码 (Symbol)</label>
