                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as AssetStatus })}
              >
                <option value="突破">突破 (Breakout)</option>
                <option value="震荡">震荡 (Ranging)</option>
                <option value="整理">整理 (Consolidation)</option>
                <option value="看涨">看涨 (Bullish)</option>
                <option value="看跌">看跌 (Bearish)</option>
                <option value="关键位置">关键位置 (Key Level)</option>
              </select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">核心观点点位/观察</label>
