          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2 px-1">交易策略</p>
          <div className="bg-gray-900 p-4 rounded-xl">
            <p className="text-sm text-gray-100 font-medium leading-relaxed italic">
              “{insight.strategy}”
            </p>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-5 border-t border-gray-50 flex justify-end items-center gap-2">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all flex items-center gap-2 text-xs font-bold"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all flex items-center gap-2 text-xs font-bold"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

