const getStatusColor = (status: AssetStatus) => {
  switch (status) {
    case '突破': return 'bg-green-50 text-green-600 border-green-200';
    case '看涨': return 'bg-blue-50 text-blue-600 border-blue-200';
    case '看跌': return 'bg-red-50 text-red-600 border-red-200';
    case '关键位置': return 'bg-orange-50 text-orange-600 border-orange-200';
    default: return 'bg-gray-50 text-gray-500 border-gray-200';
  }
};

