import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 按日期分组生成时间轴
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    // 按时间倒序
    return [...result].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [insights, activeCategory, selectedMonth]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { 
        ...i, 
        ...data, 
        updatedAt: data.updatedAt || i.updatedAt 
      } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col">
      {/* 居中设计的导航栏 */}
      <header className="sticky top-0 z-40 bg-white/90 backdrop-blur-xl border-b border-gray-100 px-6 py-4">
        <div className="max-w-7xl mx-auto flex flex-col gap-5">
          <div className="flex items-center justify-between relative h-12">
            {/* 左侧图标 */}
            <div className="flex items-center">
              <div className="bg-gray-900 p-2.5 rounded-2xl shadow-lg shadow-gray-200">
                <LayoutGrid className="w-5 h-5 text-white" />
              </div>
            </div>

            {/* 中间居中标题 */}
            <div className="absolute left-1/2 -translate-x-1/2 text-center">
              <h1 className="text-2xl font-black text-gray-900 tracking-tight leading-none mb-1">市场周刊</h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.2em] whitespace-nowrap">TRADING JOURNAL PRO</p>
            </div>

            {/* 右侧按钮 */}
            <div className="flex items-center">
              <button 
                onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
                className="bg-red-500 text-white px-5 py-2.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2 shadow-lg shadow-red-100 font-bold text-sm"
              >
                <Plus className="w-4 h-4" />
                <span className="hidden sm:inline">记录记录</span>
              </button>
            </div>
          </div>

          {/* 居中分类导航 */}
          <nav className="flex justify-center items-center gap-1 overflow-x-auto no-scrollbar pb-1">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                  activeCategory === cat 
                    ? 'bg-gray-900 text-white shadow-md shadow-gray-200 scale-105' 
                    : 'text-gray-400 hover:text-gray-900 hover:bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-6 py-10 w-full flex flex-col lg:flex-row gap-10">
        {/* 左侧边栏：时间轴归档 */}
        <aside className="lg:w-56 space-y-10 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">时间轴归档</h3>
            </div>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                  selectedMonth === null ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                }`}
              >
                <span className="flex items-center gap-2">
                  <Hash className={`w-3.5 h-3.5 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                    selectedMonth === month ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Calendar className={`w-3.5 h-3.5 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* 主内容区域 */}
        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-8">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <span className="h-1.5 w-6 bg-red-500 rounded-full"></span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  当前视图: {activeCategory} · {selectedMonth || '所有时间轴'}
                </span>
              </div>
              <h2 className="text-3xl font-bold text-gray-900 tracking-tight">
                市场观点
              </h2>
            </div>
            <div className="text-sm text-gray-400 font-medium bg-white px-4 py-1.5 rounded-full border border-gray-100">
              共计 <span className="text-gray-900 font-bold">{filteredInsights.length}</span> 条见解
            </div>
          </div>

          {filteredInsights.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
              {filteredInsights.map(insight => (
                <MarketCard 
                  key={insight.id} 
                  insight={insight} 
                  onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                  onDelete={handleDeleteInsight}
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white rounded-[3rem] border border-gray-100 shadow-sm">
              <div className="max-w-xs mx-auto">
                <div className="w-16 h-16 bg-gray-50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                  <Clock className="w-8 h-8 text-gray-200" />
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-2">暂无匹配记录</h3>
                <p className="text-sm text-gray-400 mb-8 leading-relaxed">
                  在该筛选条件下未找到任何分析。尝试更换分类或查看其他月份。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-gray-900 rounded-2xl font-bold text-sm text-white hover:bg-black transition-all shadow-xl shadow-gray-200"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* 页脚 */}
      <footer className="mt-auto border-t border-gray-100 py-10 bg-white">
        <div className="max-w-7xl mx-auto px-6 text-center">
          <p className="text-[10px] text-gray-300 font-bold uppercase tracking-[0.3em]">个人交易日记系统 · 洞察记录与回溯</p>
        </div>
      </footer>

      {/* 弹窗表单 */}
      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

