export default App;

export type AssetStatus = '突破' | '震荡' | '整理' | '看跌' | '看涨' | '关键位置';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  keyLevel?: string;
  updatedAt: number;
  isCompleted?: boolean;
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
}

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleComplete?: (id: string) => void;
}

const getStatusColor = (status: AssetStatus) => {
  switch (status) {
    case '突破': return 'bg-white/80 text-green-600 border-green-200';
    case '看涨': return 'bg-white/80 text-blue-600 border-blue-200';
    case '看跌': return 'bg-white/80 text-red-600 border-red-200';
    case '关键位置': return 'bg-white/80 text-orange-600 border-orange-200';
    default: return 'bg-white/80 text-gray-500 border-gray-200';
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleComplete }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const isCompleted = insight.isCompleted;

  return (
    <div className={`group relative border rounded-3xl p-6 transition-all duration-500 flex flex-col h-full hover:shadow-2xl ${
      isCompleted 
        ? 'bg-emerald-50/60 border-emerald-200 shadow-emerald-50' 
        : 'bg-rose-50/60 border-rose-200 shadow-rose-50'
    }`}>
      {/* 顶部状态标记 */}
      <div className="absolute -top-3 left-6 flex gap-2">
        <button 
          onClick={() => onToggleComplete?.(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm transition-all ${
            isCompleted 
              ? 'bg-emerald-500 text-white hover:bg-emerald-600' 
              : 'bg-rose-500 text-white hover:bg-rose-600'
          }`}
        >
          {isCompleted ? <CheckCircle2 className="w-3 h-3" /> : <Circle className="w-3 h-3" />}
          {isCompleted ? '已结束' : '进行中'}
        </button>
      </div>

      <div className="flex justify-between items-start mb-5 gap-4 pt-2">
        <div className="flex-grow">
          <div className="flex items-center gap-2 mb-1">
            <h3 className="text-2xl font-black text-gray-900 leading-tight">{insight.symbol}</h3>
          </div>
          <div className="flex items-center text-[10px] text-gray-500/70 gap-1 font-bold">
            <Calendar className="w-3 h-3" />
            {date}
          </div>
        </div>
        {/* 行情状态标签 */}
        <div className={`px-4 py-1.5 rounded-2xl text-xs font-black border-2 flex items-center justify-center shrink-0 min-w-[72px] shadow-sm ${getStatusColor(insight.status)}`}>
          {insight.status}
        </div>
      </div>

      <div className="space-y-4 flex-grow">
        <div className={`p-4 rounded-2xl border transition-colors ${
          isCompleted ? 'bg-white/40 border-emerald-100' : 'bg-white/40 border-rose-100'
        }`}>
          <p className={`text-[10px] font-black uppercase tracking-wider mb-2 ${isCompleted ? 'text-emerald-400' : 'text-rose-400'}`}>核心观察</p>
          <p className="text-sm text-gray-800 leading-relaxed font-semibold">{insight.focusPoints}</p>
        </div>

        {insight.keyLevel && (
          <div className={`flex items-center justify-between p-3 px-4 rounded-2xl border ${
            isCompleted ? 'bg-emerald-500/10 border-emerald-200/50' : 'bg-rose-500/10 border-rose-200/50'
          }`}>
            <p className={`text-[10px] font-black uppercase tracking-wider ${isCompleted ? 'text-emerald-500' : 'text-rose-500'}`}>关键点位</p>
            <p className={`text-lg font-black tracking-tight ${isCompleted ? 'text-emerald-600' : 'text-rose-600'}`}>{insight.keyLevel}</p>
          </div>
        )}

        <div>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider mb-2 px-1">交易策略</p>
          <div className={`p-4 rounded-2xl border-l-4 ${
            isCompleted 
              ? 'bg-gray-900 border-emerald-500 shadow-lg shadow-gray-200' 
              : 'bg-gray-900 border-rose-500 shadow-lg shadow-gray-200'
          }`}>
            <p className="text-sm text-gray-100 font-bold leading-relaxed italic">
              “{insight.strategy}”
            </p>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-5 border-t border-gray-100/50 flex justify-end items-center gap-2">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-white rounded-xl transition-all flex items-center gap-2 text-xs font-black"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-white rounded-xl transition-all flex items-center gap-2 text-xs font-black"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

