import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 按日期分组生成时间轴
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    // 按时间倒序
    return [...result].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [insights, activeCategory, selectedMonth]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { 
        ...i, 
        ...data, 
        updatedAt: data.updatedAt || i.updatedAt 
      } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        isCompleted: data.isCompleted ?? false,
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleComplete = (id: string) => {
    setInsights(prev => prev.map(i => 
      i.id === id ? { ...i, isCompleted: !i.isCompleted } : i
    ));
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col">
      {/* 居中设计的导航栏 */}
      <header className="sticky top-0 z-40 bg-white/90 backdrop-blur-xl border-b border-gray-100 px-6 py-4">
        <div className="max-w-7xl mx-auto flex flex-col gap-5">
          <div className="flex items-center justify-between h-12">
            {/* 左侧图标和标题 */}
            <div className="flex items-center gap-4">
              <div className="bg-gray-900 p-2.5 rounded-2xl shadow-lg shadow-gray-200">
                <LayoutGrid className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-2xl font-black text-gray-900 tracking-tight leading-none">市场周刊</h1>
            </div>

            {/* 右侧按钮 */}
            <div className="flex items-center">
              <button 
                onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
                className="bg-red-500 text-white px-5 py-2.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2 shadow-lg shadow-red-100 font-bold text-sm"
              >
                <Plus className="w-4 h-4" />
                <span className="hidden sm:inline">记录记录</span>
              </button>
            </div>
          </div>

          {/* 居中分类导航 */}
          <nav className="flex justify-center items-center gap-1 overflow-x-auto no-scrollbar pb-1">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                  activeCategory === cat 
                    ? 'bg-gray-900 text-white shadow-md shadow-gray-200 scale-105' 
                    : 'text-gray-400 hover:text-gray-900 hover:bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-6 py-10 w-full flex flex-col lg:flex-row gap-10">
        {/* 左侧边栏：时间轴归档 */}
        <aside className="lg:w-56 space-y-10 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">时间轴归档</h3>
            </div>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                  selectedMonth === null ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                }`}
              >
                <span className="flex items-center gap-2">
                  <Hash className={`w-3.5 h-3.5 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                    selectedMonth === month ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Calendar className={`w-3.5 h-3.5 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* 主内容区域 */}
        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-8">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <span className="h-1.5 w-6 bg-red-500 rounded-full"></span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  当前视图: {activeCategory} · {selectedMonth || '所有时间轴'}
                </span>
              </div>
              <h2 className="text-3xl font-bold text-gray-900 tracking-tight">
                市场观点
              </h2>
            </div>
            <div className="text-sm text-gray-400 font-medium bg-white px-4 py-1.5 rounded-full border border-gray-100">
              共计 <span className="text-gray-900 font-bold">{filteredInsights.length}</span> 条见解
            </div>
          </div>

          {filteredInsights.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
              {filteredInsights.map(insight => (
                <MarketCard 
                  key={insight.id} 
                  insight={insight} 
                  onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                  onDelete={handleDeleteInsight}
                  onToggleComplete={handleToggleComplete}
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white rounded-[3rem] border border-gray-100 shadow-sm">
              <div className="max-w-xs mx-auto">
                <div className="w-16 h-16 bg-gray-50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                  <Clock className="w-8 h-8 text-gray-200" />
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-2">暂无匹配记录</h3>
                <p className="text-sm text-gray-400 mb-8 leading-relaxed">
                  在该筛选条件下未找到任何分析。尝试更换分类或查看其他月份。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-gray-900 rounded-2xl font-bold text-sm text-white hover:bg-black transition-all shadow-xl shadow-gray-200"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* 页脚 */}
      <footer className="mt-auto border-t border-gray-100 py-10 bg-white">
        <div className="max-w-7xl mx-auto px-6 text-center">
          <p className="text-[10px] text-gray-300 font-bold uppercase tracking-[0.3em]">个人交易日记系统 · 洞察记录与回溯</p>
        </div>
      </footer>

      {/* 弹窗表单 */}
      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

export type AssetStatus = '突破' | '震荡' | '整理' | '看跌' | '看涨' | '关键位置';
export type CompletionStatus = '进行中' | '已完成' | '已失效';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  keyLevel?: string;
  updatedAt: number;
  completionStatus: CompletionStatus;
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
}

import React from 'react';
import { MarketInsight, AssetStatus, CompletionStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusColor = (status: AssetStatus) => {
  switch (status) {
    case '突破': return 'bg-white/80 text-green-600 border-green-200';
    case '看涨': return 'bg-white/80 text-blue-600 border-blue-200';
    case '看跌': return 'bg-white/80 text-red-600 border-red-200';
    case '关键位置': return 'bg-white/80 text-orange-600 border-orange-200';
    default: return 'bg-white/80 text-gray-500 border-gray-200';
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const status = insight.completionStatus;

  const getCardStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-50/60 border-emerald-200 shadow-emerald-50';
      case '已失效': return 'bg-slate-100/60 border-slate-200 shadow-slate-50 opacity-80';
      default: return 'bg-rose-50/60 border-rose-200 shadow-rose-50';
    }
  };

  const getTagStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-500 text-white hover:bg-emerald-600';
      case '已失效': return 'bg-slate-400 text-white hover:bg-slate-500';
      default: return 'bg-rose-500 text-white hover:bg-rose-600';
    }
  };

  const getStatusIcon = () => {
    switch (status) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-3xl p-6 transition-all duration-500 flex flex-col h-full hover:shadow-2xl ${getCardStyle()}`}>
      {/* 顶部状态标记 - 点击可循环切换 */}
      <div className="absolute -top-3 left-6 flex gap-2">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm transition-all ${getTagStyle()}`}
          title="点击切换状态"
        >
          {getStatusIcon()}
          {status}
        </button>
      </div>

      <div className="flex justify-between items-start mb-5 gap-4 pt-2">
        <div className="flex-grow">
          <div className="flex items-center gap-2 mb-1">
            <h3 className="text-2xl font-black text-gray-900 leading-tight">{insight.symbol}</h3>
          </div>
          <div className="flex items-center text-[10px] text-gray-500/70 gap-1 font-bold">
            <Calendar className="w-3 h-3" />
            {date}
          </div>
        </div>
        <div className={`px-4 py-1.5 rounded-2xl text-xs font-black border-2 flex items-center justify-center shrink-0 min-w-[72px] shadow-sm ${getAssetStatusColor(insight.status)}`}>
          {insight.status}
        </div>
      </div>

      <div className="space-y-4 flex-grow">
        <div className={`p-4 rounded-2xl border transition-colors ${
          status === '已完成' ? 'bg-white/40 border-emerald-100' : status === '已失效' ? 'bg-white/40 border-slate-100' : 'bg-white/40 border-rose-100'
        }`}>
          <p className={`text-[10px] font-black uppercase tracking-wider mb-2 ${
            status === '已完成' ? 'text-emerald-400' : status === '已失效' ? 'text-slate-400' : 'text-rose-400'
          }`}>核心观察</p>
          <p className={`text-sm leading-relaxed font-semibold ${status === '已失效' ? 'text-slate-500' : 'text-gray-800'}`}>{insight.focusPoints}</p>
        </div>

        {insight.keyLevel && (
          <div className={`flex items-center justify-between p-3 px-4 rounded-2xl border ${
            status === '已完成' ? 'bg-emerald-500/10 border-emerald-200/50' : status === '已失效' ? 'bg-slate-500/10 border-slate-200/50' : 'bg-rose-500/10 border-rose-200/50'
          }`}>
            <p className={`text-[10px] font-black uppercase tracking-wider ${
              status === '已完成' ? 'text-emerald-500' : status === '已失效' ? 'text-slate-500' : 'text-rose-500'
            }`}>关键点位</p>
            <p className={`text-lg font-black tracking-tight ${
              status === '已完成' ? 'text-emerald-600' : status === '已失效' ? 'text-slate-600' : 'text-rose-600'
            }`}>{insight.keyLevel}</p>
          </div>
        )}

        <div>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider mb-2 px-1">交易策略</p>
          <div className={`p-4 rounded-2xl border-l-4 ${
            status === '已完成' 
              ? 'bg-gray-900 border-emerald-500 shadow-lg shadow-gray-200' 
              : status === '已失效'
              ? 'bg-gray-800 border-slate-500 shadow-lg shadow-gray-200 opacity-60'
              : 'bg-gray-900 border-rose-500 shadow-lg shadow-gray-200'
          }`}>
            <p className="text-sm text-gray-100 font-bold leading-relaxed italic">
              “{insight.strategy}”
            </p>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-5 border-t border-gray-100/50 flex justify-end items-center gap-2">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-white rounded-xl transition-all flex items-center gap-2 text-xs font-black"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-white rounded-xl transition-all flex items-center gap-2 text-xs font-black"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

